* { box-sizing: border-box; }

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #28352d;
  background: #f5ead7;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f5ead7;
  background-image: linear-gradient(rgba(40, 53, 45, .035) 1px, transparent 1px), linear-gradient(90deg, rgba(40, 53, 45, .035) 1px, transparent 1px);
  background-size: 24px 24px;
}

.card {
  width: min(100%, 500px);
  padding: 32px;
  border: 3px solid #28352d;
  border-radius: 8px;
  background: #fffaf0;
  box-shadow: 8px 8px 0 #d97745;
}

.pixel-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin: 0 auto 14px;
  color: #fffaf0;
  background: #42705a;
  border: 3px solid #28352d;
  font-size: 26px;
  line-height: 1;
}

.eyebrow, h1, h2, .note { text-align: center; }
.eyebrow { margin: 0; color: #a24d2b; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 6px 0; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.12; }
.intro { margin: 0 0 28px; text-align: center; color: #536158; line-height: 1.5; }

.converter { display: grid; gap: 10px; }
label { font-weight: 700; }
input, select {
  width: 100%;
  min-height: 52px;
  padding: 10px 13px;
  border: 2px solid #75847a;
  border-radius: 5px;
  color: #28352d;
  background: #fff;
  font: inherit;
}
input { margin-bottom: 8px; }
input:hover, select:hover { border-color: #42705a; }
input:focus-visible, select:focus-visible { outline: 3px solid #d97745; outline-offset: 3px; border-color: #28352d; }
input:active, select:active { background: #f5ead7; }

.results { margin-top: 26px; }
h2 { margin: 0 0 12px; font-size: 1.15rem; }
#results-list { display: grid; gap: 9px; margin: 0; padding: 0; list-style: none; }
#results-list li {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 15px;
  border: 2px solid #d7dfd5;
  border-radius: 5px;
  background: #f0f4ec;
}
.result-value { font-weight: 800; font-variant-numeric: tabular-nums; color: #315c46; }
.note { margin: 22px 0 0; color: #536158; font-size: .9rem; line-height: 1.5; }

@media (max-width: 420px) {
  .card { padding: 24px 20px; }
  body { padding: 20px 12px; }
}

const amountInput = document.getElementById('amount');
const unitSelect = document.getElementById('unit');
const resultsList = document.getElementById('results-list');

const units = [
  { key: 'cups', label: 'Cups', short: 'cups', toMillilitres: 240 },
  { key: 'tablespoons', label: 'Tablespoons', short: 'tbsp', toMillilitres: 15 },
  { key: 'teaspoons', label: 'Teaspoons', short: 'tsp', toMillilitres: 5 },
  { key: 'millilitres', label: 'Millilitres', short: 'ml', toMillilitres: 1 }
];

function updateResults() {
  const amount = Number(amountInput.value);
  const source = units.find((unit) => unit.key === unitSelect.value);
  resultsList.replaceChildren();

  if (!Number.isFinite(amount) || amount < 0 || !source) return;

  const millilitres = amount * source.toMillilitres;
  units.filter((unit) => unit.key !== source.key).forEach((unit) => {
    const item = document.createElement('li');
    const label = document.createElement('span');
    const value = document.createElement('span');
    label.textContent = unit.label;
    value.className = 'result-value';
    value.textContent = `${(millilitres / unit.toMillilitres).toFixed(1)} ${unit.short}`;
    item.append(label, value);
    resultsList.append(item);
  });
}

amountInput.addEventListener('input', updateResults);
unitSelect.addEventListener('change', updateResults);
updateResults();
